const referralLinksMissing = `-- name: ReferralLinksMissing :many
SELECT lm.contact_id FROM list_memberships lm
JOIN contacts c ON c.id = lm.contact_id AND c.erased_at IS NULL
WHERE lm.list_id = $1 AND lm.status = 'subscribed'
  AND NOT EXISTS (SELECT 1 FROM referral_links rl WHERE rl.program_id = $2 AND rl.contact_id = lm.contact_id)
ORDER BY lm.contact_id
LIMIT $3
`

type ReferralLinksMissingParams struct {
	ListID    uuid.UUID `json:"listId"`
	ProgramID uuid.UUID `json:"programId"`
	Lim       int32     `json:"lim"`
}

// Confirmed subscribers of the program's list without a link yet.
func (q *Queries) ReferralLinksMissing(ctx context.Context, arg ReferralLinksMissingParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, referralLinksMissing, arg.ListID, arg.ProgramID, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var contact_id uuid.UUID
		if err := rows.Scan(&contact_id); err != nil {
			return nil, err
		}
		items = append(items, contact_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

