const referralReferrerIPMatch = `-- name: ReferralReferrerIPMatch :one
SELECT (EXISTS (SELECT 1 FROM referral_referrer_ips ri WHERE ri.link_id = $1 AND ri.ip = $2::inet AND ri.seen_at >= $3::timestamptz)
    OR EXISTS (SELECT 1 FROM consent_events ce WHERE ce.contact_id = $4 AND ce.ip = $2::inet AND ce.occurred_at >= $3::timestamptz
               AND ce.action IN ('subscribed', 'confirmed', 'resubscribed')))::boolean AS matched
`

type ReferralReferrerIPMatchParams struct {
	LinkID     uuid.UUID  `json:"linkId"`
	Addr       netip.Addr `json:"addr"`
	Since      time.Time  `json:"since"`
	ReferrerID uuid.UUID  `json:"referrerId"`
}

// Whether ip is an address the referrer used in the last 30 days: to open
// their hub or a page of their link, or to subscribe or confirm.
func (q *Queries) ReferralReferrerIPMatch(ctx context.Context, arg ReferralReferrerIPMatchParams) (bool, error) {
	row := q.db.QueryRow(ctx, referralReferrerIPMatch,
		arg.LinkID,
		arg.Addr,
		arg.Since,
		arg.ReferrerID,
	)
	var matched bool
	err := row.Scan(&matched)
	return matched, err
}

