const referralSetConfirmed = `-- name: ReferralSetConfirmed :exec
UPDATE referrals SET confirmed_at = $1::timestamptz, status = $2, reason = $3, signals = $4,
       hold_until = $5, held_at = CASE WHEN $2 = 'review' THEN $1::timestamptz END,
       not_counted_at = CASE WHEN $2 = 'not_counted' THEN $1::timestamptz END,
       counted_at = CASE WHEN $2 = 'counted' THEN $1::timestamptz END,
       updated_at = $1::timestamptz
WHERE id = $6
`

type ReferralSetConfirmedParams struct {
	ConfirmedAt time.Time  `json:"confirmedAt"`
	Status      string     `json:"status"`
	Reason      string     `json:"reason"`
	Signals     []string   `json:"signals"`
	HoldUntil   *time.Time `json:"holdUntil"`
	ID          uuid.UUID  `json:"id"`
}

func (q *Queries) ReferralSetConfirmed(ctx context.Context, arg ReferralSetConfirmedParams) error {
	_, err := q.db.Exec(ctx, referralSetConfirmed,
		arg.ConfirmedAt,
		arg.Status,
		arg.Reason,
		arg.Signals,
		arg.HoldUntil,
		arg.ID,
	)
	return err
}

